// Packs a small JSON-serializable state object into a URL-safe string, and
// back. There's no backend to hold shared results, so the URL itself is the
// only storage — this keeps that payload compact and safe to drop straight
// into a query string.
export function encodeShareState<T>(state: T): string {
  const json = JSON.stringify(state);
  const base64 = btoa(unescape(encodeURIComponent(json)));
  return base64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

export function decodeShareState<T>(encoded: string): T | null {
  try {
    const base64 = encoded.replace(/-/g, '+').replace(/_/g, '/');
    const padded = base64 + '='.repeat((4 - (base64.length % 4)) % 4);
    const json = decodeURIComponent(escape(atob(padded)));
    return JSON.parse(json) as T;
  } catch {
    return null;
  }
}

export function buildShareUrl(path: string, state: unknown): string {
  const encoded = encodeShareState(state);
  return `${window.location.origin}${path}?d=${encoded}`;
}
